// === Tab: mySketch ===
/**
A field of fading embers breathing in the dark.
Heat rises in glowing currents while sparks drift upward like fragments of attention. 
Click an ember pocket to reignite it—the fire briefly returns before slowly collapsing back into glowing ash.

Interaction:

Click an ember cluster to reignite it and restore nearby heat currents.
Watch sparks rise and fade as the fire settles back into embers.
R — regenerate the fire.
S — save image.

**/


let embers = [];
let sparks = [];
let smoke = [];
let heatLines = [];

let t = 0;
let fireEnergy = 1.0;

const EMBER_COUNT = 520;
const HEAT_LINE_COUNT = 46;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  pixelDensity(1);
  initFire();
}

function initFire() {
  embers = [];
  sparks = [];
  smoke = [];
  heatLines = [];
  fireEnergy = 1.0;

  background(235, 65, 3);

  for (let i = 0; i < EMBER_COUNT; i++) {
    let x = randomGaussian(0, width * 0.16);
    let y = randomGaussian(height * 0.25, height * 0.035);

    embers.push({
      x,
      y,
      baseX: x,
      baseY: y,
      heat: random(0.25, 1.25),
      fuel: random(0.25, 1.0),
      size: random(2, 7),
      phase: random(TWO_PI)
    });
  }

  for (let i = 0; i < HEAT_LINE_COUNT; i++) {
    heatLines.push({
      x: random(-width * 0.23, width * 0.23),
      height: random(height * 0.16, height * 0.42),
      phase: random(TWO_PI),
      width: random(10, 38),
      heat: random(0.3, 1),
      sway: random(0.7, 1.8)
    });
  }
}

function draw() {
  background(235, 70, 3, 18);

  translate(width / 2, height / 2);
  t += 0.012;

  fireEnergy *= 0.9991;
  fireEnergy = constrain(fireEnergy, 0.28, 2.1);

  drawAshField();
  updateEmbers();
  drawSmoke();
  drawHeatColumns();
  drawEmberConnections();
  drawEmbers();
  updateSparks();

  if (frameCount % 2 === 0) spawnSpark();
  if (frameCount % 6 === 0) spawnSmoke();
}

function updateEmbers() {
  for (let e of embers) {
    let n = noise(e.baseX * 0.006, e.baseY * 0.02, t * 1.4);

    e.x =
      e.baseX +
      sin(t * 1.8 + e.phase) * 4 +
      (n - 0.5) * 18;

    e.y =
      e.baseY +
      sin(t * 2.2 + e.phase) * 3;

    e.heat += (noise(e.baseX * 0.01, e.baseY * 0.01, t * 4) - 0.48) * 0.025;
    e.heat *= 0.9993;
    e.fuel *= 0.9995;

    e.heat = constrain(e.heat, 0.08, 1.55);
    e.fuel = constrain(e.fuel, 0.03, 1.4);
  }
}

function drawHeatColumns() {
  blendMode(ADD);
  noFill();

  for (let h of heatLines) {
    let active = h.heat * fireEnergy;

    let pts = [];

    for (let y = 0; y < h.height; y += 9) {
      let p = y / h.height;

      let softSway =
        sin(t * h.sway + h.phase + p * TWO_PI * 1.8) *
        42 *
        p;

      let airDrift =
        (noise(h.x * 0.01, y * 0.018, t * 1.8 + h.phase) - 0.5) *
        h.width *
        (1.3 - p);

      var x =
        h.x * (1 - p * 0.42) +
        softSway +
        airDrift;

      pts.push({
        x,
        y: height * 0.25 - y,
        p
      });
    }

    // outer orange glow
    stroke(18, 100, 100, 3.2 * active);
    strokeWeight(9);
    beginShape();
    for (let pt of pts) {
      curveVertex(pt.x, pt.y);
    }
    endShape();

    // amber glow
    stroke(28, 100, 100, 7.5 * active);
    strokeWeight(4);
    beginShape();
    for (let pt of pts) {
      curveVertex(pt.x, pt.y);
    }
    endShape();

    // bright golden core
    stroke(40, 95, 100, 24 * active);
    strokeWeight(1.35);
    beginShape();
    for (let pt of pts) {
      curveVertex(pt.x, pt.y);
    }
    endShape();

    // occasional glowing beads along heat current
    if (random() < 0.018 * active && pts.length > 0) {
      let pt = random(pts);
      noStroke();
      fill(36, 100, 100, 34 * active);
      circle(pt.x, pt.y, random(3, 8));
      fill(48, 70, 100, 16 * active);
      circle(pt.x, pt.y, random(8, 16));
      noFill();
    }

    if (random() < 0.006 * fireEnergy) {
      spawnSparkAt(h.x, height * 0.21, false);
    }
  }

  blendMode(BLEND);
}

function drawEmberConnections() {
  blendMode(ADD);

  for (let i = 0; i < embers.length; i += 2) {
    let a = embers[i];

    for (let j = i + 1; j < embers.length; j += 5) {
      let b = embers[j];
      let d = dist(a.x, a.y, b.x, b.y);

      if (d < 42) {
        let strength = map(d, 0, 42, 1, 0);
        let heat = (a.heat + b.heat) * 0.5;

        stroke(28, 95, 100, strength * heat * 18);
        strokeWeight(strength * 0.9);
        line(a.x, a.y, b.x, b.y);
      }
    }
  }

  blendMode(BLEND);
}

function drawEmbers() {
  blendMode(ADD);
  noStroke();

  for (let e of embers) {
    let pulse = sin(t * 5 + e.phase) * 0.5 + 0.5;
    var heat = e.heat * e.fuel * fireEnergy;

    let hue = lerp(4, 42, constrain(heat, 0, 1));
    let glow = 7 + heat * 13;

    fill(hue, 95, 100, 5 * heat);
    circle(e.x, e.y, glow * 3.2);

    fill(hue + 6, 92, 100, 20 * heat);
    circle(e.x, e.y, glow * 1.2);

    fill(hue, 78, 100, 80);
    circle(e.x, e.y, e.size * (0.8 + heat * 0.9 + pulse * 0.3));

    if (heat > 0.9) {
      fill(0, 0, 100, 90);
      circle(e.x, e.y, e.size * 0.45);
    }
  }

  blendMode(BLEND);
}

function spawnSpark() {
  if (random() > fireEnergy * 0.55) return;

  var x = randomGaussian(0, width * 0.13);
  var y = height * 0.21 + random(-12, 12);

  spawnSparkAt(x, y, true);
}

function spawnSparkAt(x, y, upward) {
  let angle = upward
    ? random(-PI * 0.78, -PI * 0.22)
    : random(TWO_PI);

  let speed = upward
    ? random(1.6, 6.5) * fireEnergy
    : random(1, 4);

  sparks.push({
    x,
    y,
    vx: cos(angle) * speed,
    vy: sin(angle) * speed,
    life: random(45, 120),
    maxLife: 120,
    size: random(1.1, 4.2),
    h: random(12, 42)
  });

  if (sparks.length > 420) sparks.shift();
}

function updateSparks() {
  blendMode(ADD);
  noStroke();

  for (let i = sparks.length - 1; i >= 0; i--) {
    let s = sparks[i];

    s.x += s.vx + sin(t * 4 + s.y * 0.03) * 0.35;
    s.y += s.vy;

    s.vx *= 0.985;
    s.vy += 0.025;
    s.life--;

    var a = map(s.life, 0, s.maxLife, 0, 80);

    fill(s.h, 100, 100, a);
    ellipse(s.x, s.y, s.size, s.size * 4.2);

    fill(s.h + 12, 60, 100, a * 0.24);
    circle(s.x, s.y, s.size * 5);

    if (s.life <= 0) sparks.splice(i, 1);
  }

  blendMode(BLEND);
}

function spawnSmoke() {
  smoke.push({
    x: randomGaussian(0, width * 0.09),
    y: height * 0.18,
    vx: random(-0.25, 0.25),
    vy: random(-1.1, -0.35),
    life: random(130, 280),
    maxLife: 280,
    size: random(34, 110),
    phase: random(TWO_PI)
  });

  if (smoke.length > 130) smoke.shift();
}

function drawSmoke() {
  noStroke();

  for (let i = smoke.length - 1; i >= 0; i--) {
    var s = smoke[i];

    s.x += s.vx + sin(t * 1.7 + s.phase) * 0.25;
    s.y += s.vy;
    s.life--;

    var a = map(s.life, 0, s.maxLife, 0, 7);

    fill(230, 15, 18, a);
    circle(s.x, s.y, s.size);

    fill(235, 28, 5, a * 0.55);
    circle(s.x + 22, s.y + 8, s.size * 0.65);

    if (s.life <= 0) smoke.splice(i, 1);
  }
}

function drawAshField() {
  noStroke();

  fill(235, 45, 2, 34);
  ellipse(0, height * 0.27, width * 0.45, height * 0.08);

  for (let i = 0; i < 70; i++) {
    var x = randomGaussian(0, width * 0.2);
    var y = randomGaussian(height * 0.29, height * 0.025);

    fill(35, 10, 35, random(1, 5));
    circle(x, y, random(1, 3));
  }
}

function mousePressed() {
  fireEnergy = min(1.55, fireEnergy + 0.18);

  let mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;
  let my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2;

  for (let e of embers) {
    var d = dist(mx, my, e.x, e.y);

    if (d < 170) {
      e.heat = min(1.55, e.heat + map(d, 0, 170, 0.22, 0.02));
      e.fuel = min(1.4, e.fuel + map(d, 0, 170, 0.04, 0.005));
    }
  }

  for (let i = 0; i < 22; i++) {
    spawnSparkAt(
      mx + random(-45, 45),
      my + random(-12, 12),
      true
    );
  }
}

function keyPressed() {
  if (key === "r" || key === "R") initFire();
  if (key === "s" || key === "S") saveCanvas("beautiful-burnout-embers", "png");

  return false;
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  initFire();
}

